target.query:
import "date"
// Every diagnosed incident that overlaps the range, whatever it blamed (except a probe missing a few pings). An incident is stamped at its start: reach back a week.
// The link zooms this dashboard to the incident with a quarter of its length on either side.
from(bucket: "smokeping") |> range(start: date.sub(d: 7d, from: v.timeRangeStart), stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "loss_incident" and (r._field == "class" or r._field == "confidence" or r._field == "summary" or r._field == "end_epoch" or r._field == "minutes"))
  |> pivot(rowKey: ["_time"], columnKey: ["_field"], valueColumn: "_value")
  |> filter(fn: (r) => r.class != "probe_miss" and r.end_epoch * 1000000000 >= int(v: v.timeRangeStart))
  |> map(fn: (r) => ({_time: r._time, timeEnd: time(v: r.end_epoch * 1000000000), text: "Loss incident, " + r.class + " (" + r.confidence + " confidence, " + string(v: r.minutes) + " min): " + r.summary + " <a href=\"/d/connectivity-quality-v1?from=" + string(v: int(v: r._time) / 1000000 - int(v: r.minutes) * 15000) + "&to=" + string(v: r.end_epoch * 1000 + int(v: r.minutes) * 15000) + "\">Zoom to this window</a>", tags: "incident," + r.class}))
